import './field.js';
import './flow-select.js';
import './switch.js';
import './date-time.js';
import './setting-row.js';
import {FlowControl} from './control-base.js';
import {pulseFeedback} from './feedback.js';
import {mapIcon} from '../../../docs/design/component-map/map-icons.js';

const clone=value=>structuredClone(value),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const settingsPalette=[['teal','Бирюзовый','#58d0cf'],['blue','Синий','#76a9ff'],['indigo','Индиго','#8b93ff'],['violet','Фиолетовый','#b99aff'],['pink','Розовый','#f58bb8'],['red','Красный','#ff7b7b'],['orange','Оранжевый','#ffa35c'],['amber','Янтарный','#f2c14e'],['green','Зелёный','#6fcf7f']];
const defaults={theme:'dark',accent:'blue',density:'comfortable',startPage:'today',motionMode:'system',sound:true,haptics:true,ambient:false,radius:24,glow:16,context:10,digest:'08:30',digestEvening:'21:00',quietFrom:'23:00',quietTo:'08:00',notifyShower:'digest',notifyHabits:'timed',notifyEnglish:'digest',manualOnly:false};
const booleanKeys=new Set(['sound','haptics','ambient','manualOnly']);
const selectOptions={theme:[['dark','Тёмная'],['midnight','Ночь'],['graphite','Графит']],density:[['spacious','Свободно'],['comfortable','Обычно'],['compact','Компактно']],startPage:[['today','План'],['saved','Сохранённое'],['finance','Финансы']],motionMode:[['system','Как на устройстве'],['on','Включено'],['off','Без движения']],context:[[5,'5 сообщений'],[10,'10 сообщений'],[20,'20 сообщений']]};
for(const key of ['notifyShower','notifyHabits','notifyEnglish'])selectOptions[key]=[['digest','В сводке'],['timed','По времени'],['off','Выключено']];
const style=new CSSStyleSheet();style.replaceSync(`
:host{display:block}:host([hidden]){display:none!important}*{box-sizing:border-box}.sections{display:grid;gap:18px}.section{position:relative;min-width:0;padding:16px;border:1px solid var(--fu-line);border-radius:var(--fu-radius,24px);background:var(--fu-surface)}h2{display:flex;align-items:center;gap:9px;font-size:16px;line-height:1.3;margin:0 0 12px}h2 svg{width:24px;height:24px}h2::after{content:'';height:1px;flex:1;margin-left:8px;background:linear-gradient(90deg,color-mix(in srgb,var(--fu-accent) 32%,var(--fu-line)),var(--fu-line))}.rows{display:grid;gap:0}.row{display:grid;grid-template-columns:minmax(0,1fr) minmax(110px,47%);align-items:center;gap:12px;min-height:58px;padding:8px 0;border-bottom:1px solid var(--fu-line)}.row:last-child{border-bottom:0}.label{font-size:14px;min-width:0}.muted{font-size:12px;color:var(--fu-muted)}.row flow-select,.row flow-field{width:100%}.row flow-switch{grid-column:1/-1;margin:0 -12px}.palette{display:flex;flex-wrap:wrap;gap:9px;padding:8px 0 12px}.swatch{width:30px;height:30px;padding:3px;border:1px solid transparent;border-radius:50%;background:transparent;flex:none}.swatch span{display:block;width:22px;height:22px;border-radius:50%;background:var(--swatch)}.swatch[aria-pressed=true]{border-color:var(--fu-text)}.custom{display:flex;align-items:center;gap:10px}.custom input[type=color]{width:42px;height:42px;border:1px solid var(--fu-line);border-radius:12px;background:var(--fu-bg);padding:5px;cursor:pointer;flex:none}.custom input[type=color]::-webkit-color-swatch-wrapper{padding:0}.custom input[type=color]::-webkit-color-swatch{border:0;border-radius:7px}.custom flow-field{flex:1;min-width:0}.accent-label{display:flex;justify-content:space-between;gap:12px;margin-top:6px}.range-row{padding:11px 0;border-bottom:1px solid var(--fu-line)}.range-row:last-child{border:0}.range-head{display:flex;justify-content:space-between;font-size:14px;margin-bottom:9px}input[type=range]{display:block;width:100%;appearance:none;background:transparent;height:24px;margin:0}input[type=range]::-webkit-slider-runnable-track{height:3px;border-radius:4px;background:linear-gradient(90deg,var(--fu-accent) 0 var(--range,50%),var(--fu-line) var(--range,50%) 100%)}input[type=range]::-webkit-slider-thumb{appearance:none;width:17px;height:17px;border:2px solid var(--fu-accent);border-radius:50%;background:var(--fu-text);margin-top:-7px;box-shadow:0 0 8px color-mix(in srgb,var(--fu-accent) 15%,transparent)}.time-pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}.time-pair label{display:grid;gap:5px;font-size:12px;color:var(--fu-muted)}input[type=time]{min-width:0;width:100%;color:var(--fu-text);background:var(--fu-bg);border:1px solid var(--fu-line);border-radius:12px;padding:10px;font:inherit;color-scheme:dark}.subhead{font-size:13px;color:var(--fu-muted);margin:14px 0 5px}.status{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:48px;font-size:14px}.status span:last-child{text-align:right;color:var(--fu-muted);font-size:12px}.action-row{position:relative;display:flex;align-items:center;justify-content:space-between;gap:16px;width:100%;min-height:52px;border:0;border-bottom:1px solid var(--fu-line);border-radius:12px;padding:10px 8px;background:none;text-align:left}.action-row:last-of-type{border-bottom:0}.action-row small{display:block;color:var(--fu-muted);font-size:12px;font-weight:400;margin-top:3px}.action-row:focus-visible{outline:none}.action-row:focus-visible>span:first-child{text-decoration:underline;text-decoration-color:var(--fu-accent);text-underline-offset:5px}.action-row:active{background:color-mix(in srgb,var(--fu-accent) 6%,transparent)}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions flow-button{flex:1;min-width:130px}.notice{margin:8px 0 0;color:var(--fu-danger);font-size:12px;overflow-wrap:anywhere}.notice:empty{display:none}[data-pending]{opacity:.66}.section:focus-within{border-color:color-mix(in srgb,var(--fu-accent) 32%,var(--fu-line))}button:focus-visible,input:focus-visible{outline:2px solid var(--fu-accent);outline-offset:3px}.swatch:focus-visible{outline-offset:2px}input[type=range]:focus-visible{outline:none;filter:drop-shadow(0 1px 2px color-mix(in srgb,var(--fu-accent) 45%,transparent))}@media(min-width:760px){.sections{grid-template-columns:1fr 1fr;align-items:start}}@media(max-width:350px){.section{padding:13px}.row{grid-template-columns:minmax(0,1fr) minmax(106px,49%);gap:7px}.label{font-size:13px}}`);

/** Owner commits and applies tokens, updates model, then settle(requestId,{ok,error}). */
export class FlowSettingsWorkspace extends FlowControl{
 constructor(){super();this.shadowRoot.adoptedStyleSheets=[...this.shadowRoot.adoptedStyleSheets,style];this._model={};this._pending=new Map();this._seq=0;this._epoch=0;}
 connectedCallback(){if(!this._built)this.build();this.sync();}
 disconnectedCallback(){super.disconnectedCallback();this._epoch++;this._pending.clear();}
 feedbackTarget(event){return event?.composedPath().find(node=>node?.classList?.contains('section'))||null;}
 set model(value){this._model=clone(value||{});if(this._built)this.sync();}
 get model(){return clone(this._model);}
 get dirty(){return false;}
 get hasOpenEditor(){return false;}
 closeWindows(){this._epoch++;this._pending.clear();this.sync();}
 value(key){return this._model[key]??defaults[key];}
 select(key,label){return `<div class="row"><span class="label">${label}</span><flow-select data-key="${key}" aria-label="${label}" label="${label}" presentation="dialog">${selectOptions[key].map(([value,text])=>`<option value="${value}">${text}</option>`).join('')}</flow-select></div>`;}
 toggle(key,label){return `<div class="row"><flow-switch data-key="${key}" label="${label}"></flow-switch></div>`;}
 action(action,title,description=''){return `<button class="action-row" data-action="${action}" type="button"><span>${title}${description?`<small>${description}</small>`:''}</span><span aria-hidden="true">›</span></button>`;}
 section(id,icon,title,body){return `<section class="section" data-section="${id}"><h2>${mapIcon(icon)}${title}</h2>${body}<p class="notice" role="status"></p></section>`;}
 build(){this._built=true;this.shadowRoot.innerHTML=`<div class="sections">
 ${this.section('appearance','settings','Внешний вид',`<div class="rows">${this.select('theme','Тема')}${this.select('density','Плотность')}${this.select('startPage','При открытии')}</div><div class="accent-label"><span>Акцент</span><span class="muted" data-accent-name></span></div><div class="palette">${settingsPalette.map(([key,name,color])=>`<button class="swatch" data-accent="${key}" aria-label="${name}" style="--swatch:${color}"><span></span></button>`).join('')}</div><div class="custom"><input type="color" aria-label="Свой акцентный цвет"><flow-field data-key="accentHex" placeholder="#76A9FF" aria-label="Код акцентного цвета"></flow-field></div>${this.action('design','Классический дизайн')}`)}
 ${this.section('living','more','Живой отклик',`<div class="rows">${this.select('motionMode','Движение')}${this.toggle('sound','Звуковые отклики')}${this.toggle('haptics','Тактильный отклик')}${this.toggle('ambient','Звуковая атмосфера')}</div><div class="range-row"><div class="range-head"><span>Скругление</span><output data-output="radius"></output></div><input data-key="radius" aria-label="Скругление" type="range" min="12" max="36" step="1"></div><div class="range-row"><div class="range-head"><span>Свечение</span><output data-output="glow"></output></div><input data-key="glow" aria-label="Свечение" type="range" min="0" max="25" step="1"></div>`)}
 ${this.section('bot','today','Бот и уведомления',`<div class="time-pair"><label>Утро<flow-date-time kind="time" data-key="digest" aria-label="Утренняя сводка"></flow-date-time></label><label>Вечер<flow-date-time kind="time" data-key="digestEvening" aria-label="Вечерняя сводка"></flow-date-time></label></div><p class="subhead">Не беспокоить</p><div class="time-pair"><label>С<flow-date-time kind="time" data-key="quietFrom" aria-label="Начало тихого времени"></flow-date-time></label><label>До<flow-date-time kind="time" data-key="quietTo" aria-label="Конец тихого времени"></flow-date-time></label></div><div class="rows">${this.select('notifyShower','Для себя')}${this.select('notifyHabits','Привычки')}${this.select('notifyEnglish','Английский')}${this.select('context','Контекст')}${this.toggle('manualOnly','Добавлять без обработки ИИ')}</div>`)}
 ${this.section('connections','materials','Подключения',`<div class="status"><span>Google Календарь</span><span data-status="calendar"></span></div>${this.action('calendar','Подключить календарь','Через бота Flow')}${this.action('browser','Расширение браузера')}${this.action('connections','Управление подключениями')}<div data-usage></div>`)}
 ${this.section('device','pc','Телефон и виджеты',`<div class="status"><span>Телефон</span><span data-status="phone"></span></div><div class="status"><span>Внешний островок</span><span data-status="island"></span></div>${this.action('phone-island','Островок поверх приложений')}${this.action('phone-permissions','Разрешения телефона')}${this.action('widgets','Виджеты заметок и календаря')}${this.action('camera','Камера и свет')}`)}
 ${this.section('data','docs','Данные',`<div class="actions"><flow-button data-action="export-json" label="Экспорт JSON" stretch></flow-button><flow-button data-action="export-csv" label="Экспорт CSV" stretch></flow-button></div>${this.action('storage','Хранилище и резервная копия')}${this.action('reset','Сбросить настройки')}`)}
 </div>`;
 this.shadowRoot.addEventListener('change',event=>{const node=event.composedPath().find(item=>item?.dataset?.key);if(!node)return;const key=node.dataset.key;if(key==='accentHex')this.request('accent',node.value);else this.request(key,booleanKeys.has(key)?node.hasAttribute('checked'):['radius','glow','context'].includes(key)?Number(node.value):node.value);});
 this.shadowRoot.querySelectorAll('[data-accent]').forEach(button=>button.onclick=()=>this.request('accent',button.dataset.accent));
 this.shadowRoot.querySelector('input[type=color]').onchange=event=>this.request('accent',event.target.value);
 this.shadowRoot.querySelectorAll('input[type=range]').forEach(input=>input.oninput=()=>this.output(input.dataset.key,input.value));
 this.shadowRoot.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>this.intent(button.dataset.action,button)));
 }
 output(key,value){const input=this.shadowRoot.querySelector(`input[data-key="${key}"]`);if(input)input.style.setProperty('--range',((Number(value)-Number(input.min))/(Number(input.max)-Number(input.min))*100)+'%');this.shadowRoot.querySelector(`[data-output="${key}"]`).textContent=value+(key==='glow'?'%':' px');}
 sync(){if(!this._built)return;for(const node of this.shadowRoot.querySelectorAll('[data-key]')){const key=node.dataset.key;if(key==='accentHex')continue;const pending=[...this._pending.values()].find(item=>item.key===key);const value=pending?pending.value:this.value(key);node.toggleAttribute('data-pending',!!pending);if(booleanKeys.has(key))node.toggleAttribute('checked',!!value);else if(node.value!==String(value))node.value=String(value);if(node.localName==='flow-select')node.value=String(value);if(['radius','glow'].includes(key))this.output(key,value);}
 const accentPending=[...this._pending.values()].find(item=>item.key==='accent'),accent=accentPending?.value??this.value('accent'),palette=settingsPalette.find(item=>item[0]===accent),color=palette?.[2]||(/^#[0-9a-f]{6}$/i.test(accent)?accent:'#76a9ff');
 this.shadowRoot.querySelectorAll('[data-accent]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.accent===accent)));
 this.shadowRoot.querySelector('[data-accent-name]').textContent=palette?.[1]||'Свой';
 this.shadowRoot.querySelector('input[type=color]').value=color;const hex=this.shadowRoot.querySelector('[data-key=accentHex]');if(!hex.matches(':focus-within')&&hex.value.toLowerCase()!==color.toLowerCase())hex.value=color.toUpperCase();
 const phone=this._model.phone||{},connected=phone.linked===true||phone.connected===true;
 this.shadowRoot.querySelector('[data-status=phone]').textContent=connected?(phone.name||phone.model||'Подключён'):'Не подключён';
 this.shadowRoot.querySelector('[data-status=island]').textContent=phone.islandRunning===true?'Работает':phone.islandEnabled===true?'Включён · нет подтверждения работы':'Не подключён';
 this.shadowRoot.querySelector('[data-status=calendar]').textContent=this._model.gcal||this._model.connections?.calendar?.connected?'Подключён':'Не подключён';
 const usage=this._model.openRouter;this.shadowRoot.querySelector('[data-usage]').textContent=usage&&Number.isFinite(Number(usage.left))?`Осталось ${new Intl.NumberFormat('ru-RU').format(usage.left)} · сегодня ${usage.today??'—'}`:'';
 }
 request(key,value){if(key==='accent'){value=String(value).trim();if(!settingsPalette.some(item=>item[0]===value)&&!/^#[0-9a-f]{6}$/i.test(value)){this.notice('appearance','Укажи цвет в формате #RRGGBB');return false;}}if(['digest','digestEvening','quietFrom','quietTo'].includes(key)&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(value))return false;if(['radius','glow'].includes(key))value=Math.max(key==='radius'?12:0,Math.min(key==='radius'?36:25,Number(value)));if(!Number.isFinite(value)&&typeof value==='number')return false;
 if(this.value(key)===value&&!this._pending.size)return true;for(const[id,item]of this._pending)if(item.key===key)this._pending.delete(id);
 const requestId=`settings-${this._epoch}-${++this._seq}`,entry={key,value,epoch:this._epoch};this._pending.set(requestId,entry);this.notice(this.sectionFor(key),'');this.sync();this.dispatchEvent(new CustomEvent('flow-settings-change',{detail:{key,value,requestId},bubbles:true,composed:true,cancelable:true}));return requestId;
 }
 sectionFor(key){return ['theme','accent','density','startPage'].includes(key)?'appearance':['motionMode','sound','haptics','ambient','radius','glow'].includes(key)?'living':'bot';}
 intent(action,node){const requestId=`settings-action-${this._epoch}-${++this._seq}`;this._pending.set(requestId,{action,epoch:this._epoch,section:node.closest('.section').dataset.section});this.notice(node.closest('.section').dataset.section,'Ожидаю приложение…');this.dispatchEvent(new CustomEvent('flow-settings-intent',{detail:{action,requestId},bubbles:true,composed:true,cancelable:true}));}
 settle(requestId,result={}){const pending=this._pending.get(requestId);if(!pending||pending.epoch!==this._epoch)return false;this._pending.delete(requestId);if(result.ok&&pending.key)this._model[pending.key]=result.value??pending.value;this.sync();const section=pending.section||this.sectionFor(pending.key);this.notice(section,result.ok?'':result.error||'Изменение не применено');if(result.ok)pulseFeedback(this,this.shadowRoot.querySelector(`[data-section="${section}"]`),{tone:'action'});return true;}
 notice(section,message){const node=this.shadowRoot.querySelector(`[data-section="${section}"] .notice`);if(node)node.textContent=message;}
}
if(!customElements.get('flow-settings-workspace'))customElements.define('flow-settings-workspace',FlowSettingsWorkspace);





